package com.alsafa.native4;
import android.app.*;import android.graphics.Color;import android.text.InputType;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.util.List;
public final class CoreProductPanelBinder{
 private final Activity a;private final Native4Services services;private final TextView status;private final EditText name,qty,price,ref,barcode,brand,cost,dialColor,strapType,caseColor;private final Spinner currency,gender,displayType;
 public CoreProductPanelBinder(Activity a,Native4Services services,TextView status){this.a=a;this.services=services;this.status=status;name=a.findViewById(R.id.productName);qty=a.findViewById(R.id.productQuantity);price=a.findViewById(R.id.productPrice);Button save=a.findViewById(R.id.saveProduct);ViewGroup parent=(ViewGroup)save.getParent();int at=parent.indexOfChild(save);ref=field("REF / رقم الموديل",InputType.TYPE_CLASS_TEXT);barcode=field("الباركود الأساسي",InputType.TYPE_CLASS_TEXT);brand=field("الماركة",InputType.TYPE_CLASS_TEXT);cost=field("تكلفة الشراء",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);currency=spinner(AccountingChoices.CURRENCY_LABELS);gender=spinner(new String[]{"غير محدد","ذكر","أنثى"});displayType=spinner(new String[]{"غير محدد","عقارب","رقمية"});dialColor=field("لون المينا",InputType.TYPE_CLASS_TEXT);strapType=field("نوع / لون الحزام",InputType.TYPE_CLASS_TEXT);caseColor=field("لون الهيكل",InputType.TYPE_CLASS_TEXT);style(name,"اسم المنتج");style(qty,"الكمية");style(price,"سعر البيع");parent.addView(ref,at++);parent.addView(barcode,at++);parent.addView(brand,at++);parent.addView(cost,at++);parent.addView(currency,at++);parent.addView(gender,at++);parent.addView(displayType,at++);parent.addView(dialColor,at++);parent.addView(strapType,at++);parent.addView(caseColor,at);save.setText("✓ حفظ المنتج");save.setTextColor(Color.WHITE);save.setTextSize(18);save.setMinHeight(dp(64));save.setBackgroundResource(R.drawable.alsafa_primary);save.setOnClickListener(v->checkThenSave());}
 private Spinner spinner(String[] values){Spinner s=new Spinner(a);s.setMinimumHeight(dp(56));s.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,values));s.setBackgroundResource(R.drawable.alsafa_card);return s;}
 private EditText field(String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);style(e,hint);e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}
 private void style(EditText e,String hint){e.setHint(hint);e.setGravity(Gravity.END);e.setMinHeight(dp(56));e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackgroundResource(R.drawable.alsafa_card);}
 private void checkThenSave(){try{String n=name.getText().toString().trim();if(n.isEmpty())throw new IllegalArgumentException("اسم المنتج مطلوب");List<ProductStore.Duplicate> d=services.products.duplicates(n,barcode.getText().toString());if(d.isEmpty()){saveNow();return;}StringBuilder m=new StringBuilder("يوجد منتج مشابه. لن نحذف أو نستبدل أي منتج.\n\n");for(ProductStore.Duplicate x:d)m.append(x.sameBarcode?"نفس الباركود: ":"نفس الاسم: ").append(x.label()).append("\n\n");m.append("راجع المنتج، ثم اختر الإضافة فقط إذا كان منتجاً مختلفاً فعلاً.");new AlertDialog.Builder(a).setTitle("تنبيه تكرار المنتج").setMessage(m.toString()).setNegativeButton("رجوع",null).setPositiveButton("إضافة رغم ذلك",(x,w)->saveNow()).show();}catch(Exception e){error(e);}}
 private void saveNow(){try{String n=name.getText().toString().trim();int q=Integer.parseInt(qty.getText().toString().trim());double p=number(price),c=number(cost);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());String id=services.products.create(n,ref.getText().toString(),barcode.getText().toString(),brand.getText().toString(),q,p,c,cur,selected(gender),selected(displayType),dialColor.getText().toString(),strapType.getText().toString(),caseColor.getText().toString());Native4BackgroundSync.request(a);clear();status.setText("✓ تم حفظ المنتج — المرجع: "+id);}catch(Exception e){error(e);}}
 private static String selected(Spinner s){return s.getSelectedItemPosition()==0?"":String.valueOf(s.getSelectedItem());}private static double number(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private void error(Exception e){status.setText("لم يُحفظ المنتج: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private void clear(){name.setText("");qty.setText("");price.setText("");ref.setText("");barcode.setText("");brand.setText("");cost.setText("");gender.setSelection(0);displayType.setSelection(0);dialColor.setText("");strapType.setText("");caseColor.setText("");}
}